/* Global Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
}

header, nav, main, footer {
  display: block;
}

/* Header Styles */
header {
  background-color: #333;
  color: #fff;
  padding: 1em;
  text-align: center;
}

/* Navigation Styles */
nav {
  background-color: #444;
  padding: 0.5em;
}

nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

nav li {
  display: inline-block;
  margin-right: 20px;
}

nav a {
  color: #fff;
  text-decoration: none;
}

/* Main Content Styles */
main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2em;
}

/* Footer Styles */
footer {
  background-color: #333;
  color: #fff;
  padding: 1em;
  text-align: center;
  clear: both;
}

/* Responsive Design */
@media only screen and (max-width: 600px) {
  nav {
    flex-direction: column;
  }

  nav li {
    display: block;
    margin-right: 0;
  }
}
